(()=>{const data=JSON.parse(document.getElementById('cp-album').textContent),d=document.querySelector('.cp-lightbox'),im=d.querySelector('img'),caption=d.querySelector('.cp-caption'),counter=d.querySelector('.cp-counter'),prev=d.querySelector('.cp-prev'),next=d.querySelector('.cp-next'),original=d.querySelector('.cp-original');let index=0;const show=()=>{const x=data[index];im.src=x.src;im.alt=x.title;caption.textContent=x.title;counter.textContent=(index+1)+' / '+data.length;prev.disabled=index===0;next.disabled=index===data.length-1;original.href=x.src;d.scrollTop=0;};const step=n=>{if(index+n<0||index+n>=data.length)return;index+=n;show();};document.querySelectorAll('[data-album-index]').forEach(b=>b.addEventListener('click',()=>{index=Number(b.dataset.albumIndex);show();d.showModal();}));prev.onclick=()=>step(-1);next.onclick=()=>step(1);d.querySelector('.cp-close').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d)d.close();});d.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();step(e.key==='ArrowLeft'?-1:1);}});let start;d.addEventListener('touchstart',e=>{start=e.changedTouches[0].clientX;},{passive:true});d.addEventListener('touchend',e=>{if(start===undefined)return;const dx=e.changedTouches[0].clientX-start;start=undefined;if(Math.abs(dx)>60)step(dx<0?1:-1);},{passive:true});d.addEventListener('close',()=>im.removeAttribute('src'));})();